import React, { useState, useEffect } from 'react';

const LeaderboardPage = () => {
  const [leaderboardData, setLeaderboardData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchLeaderboard = async () => {
      try {
        const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/stats/leaderboard`);
        const data = await response.json();

        // Ensure data is an array before setting state
        if (Array.isArray(data)) {
          setLeaderboardData(data);
        } else if (data && Array.isArray(data.leaderboard)) {
          // If the API returns an object with a leaderboard property that contains the array
          setLeaderboardData(data.leaderboard);
        } else {
          // Fallback to empty array if unexpected format
          setLeaderboardData([]);
        }

        setLoading(false);
      } catch (error) {
        console.error('Error fetching leaderboard:', error);
        setLeaderboardData([]);
        setLoading(false);
      }
    };

    fetchLeaderboard();
  }, []);

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading leaderboard...</p>
      </div>
    );
  }

  return (
    <div className="leaderboard-page">
      <div className="card">
        <h2 className="card-title">Leaderboard</h2>

        <div className="leaderboard-tabs">
          <button className="tab-btn active">Top Players</button>
          <button className="tab-btn">Most Wins</button>
          <button className="tab-btn">Highest Streak</button>
        </div>

        <div className="table-responsive">
          <table className="table">
            <thead>
              <tr>
                <th>Rank</th>
                <th>Player</th>
                <th>Balance</th>
                <th>Wins</th>
                <th>Losses</th>
                <th>Win Rate</th>
              </tr>
            </thead>
            <tbody>
              {Array.isArray(leaderboardData) && leaderboardData.length > 0 ? (
                leaderboardData.map((player, index) => (
                  <tr key={player.id || index}>
                    <td>
                      <span className={`rank-badge rank-${index + 1}`}>
                        #{index + 1}
                      </span>
                    </td>
                    <td>
                      <div className="player-info">
                        <img 
                          src={player.avatar || '/default-avatar.png'} 
                          alt="Avatar" 
                          className="player-avatar"
                          onError={(e) => {
                            e.target.src = '/default-avatar.png';
                          }}
                        />
                        <span>{player.displayName}</span>
                      </div>
                    </td>
                    <td>{player.balance?.toLocaleString() || 0} AMP</td>
                    <td>{player.gamesWon || 0}</td>
                    <td>{player.gamesLost || 0}</td>
                    <td>{player.winRate ? `${player.winRate}%` : '0%'}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="6" style={{ textAlign: 'center' }}>
                    No data available
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default LeaderboardPage;
